namespace Relay.Api.Http;

public sealed record ActivityHealthRequest(
    [FromRoute] int AccountId,
    [FromQuery, IsoDate] string? Week,
    [FromQuery, ActivityTypeName] string? Type);
using System.Globalization;
using Relay.Core.Queries;

namespace Relay.Api.Http;

public static class ActivityHealthRequestExtensions
{
    public static DateOnly? ParsedWeek(this ActivityHealthRequest request) =>
        request.Week is null
            ? null
            : DateOnly.ParseExact(request.Week, IsoDateAttribute.Format, CultureInfo.InvariantCulture);

    public static ActivityType ParsedEventType(this ActivityHealthRequest request) =>
        request.Type is not null && ActivityTypeNames.TryParse(request.Type, out var eventType)
            ? eventType
            : ActivityType.All;
}
using System.ComponentModel.DataAnnotations;
using System.Globalization;

namespace Relay.Api.Http;

[AttributeUsage(AttributeTargets.Parameter | AttributeTargets.Property)]
public sealed class IsoDateAttribute : ValidationAttribute
{
    public const string Format = "yyyy-MM-dd";

    public IsoDateAttribute()
        : base($"The field {{0}} must be a date in {Format} format.")
    {
    }

    public override bool IsValid(object? value) =>
        value is null
        || (value is string text
            && DateOnly.TryParseExact(text, Format, CultureInfo.InvariantCulture, DateTimeStyles.None, out _));
}
using System.ComponentModel.DataAnnotations;

namespace Relay.Api.Http;

[AttributeUsage(AttributeTargets.Parameter | AttributeTargets.Property)]
public sealed class ActivityTypeNameAttribute : ValidationAttribute
{
    public ActivityTypeNameAttribute()
        : base($"The field {{0}} must be one of: {string.Join(", ", ActivityTypeNames.Names)}.")
    {
    }

    public override bool IsValid(object? value) =>
        value is null || (value is string name && ActivityTypeNames.TryParse(name, out _));
}
using System.Collections.Frozen;
using System.Text.Json;
using Relay.Core.Queries;

namespace Relay.Api.Http;

public static class ActivityTypeNames
{
    private static readonly FrozenDictionary<string, ActivityType> ActivityTypesByName =
        Enum.GetValues<ActivityType>().ToFrozenDictionary(WireName, StringComparer.Ordinal);

    public static IReadOnlyList<string> Names { get; } = [.. Enum.GetValues<ActivityType>().Select(WireName)];

    public static bool TryParse(string name, out ActivityType activityType) =>
        ActivityTypesByName.TryGetValue(name, out activityType);

    private static string WireName(ActivityType activityType) =>
        JsonNamingPolicy.SnakeCaseLower.ConvertName(activityType.ToString());
}
using Relay.Core.Queries;

namespace Relay.Core.Accounts;

public sealed class AccountService(IAccountQueries accountQueries) : IAccountService
{
    public async Task<IReadOnlyList<AccountListItem>> ListAsync(CancellationToken cancellationToken)
    {
        var accounts = await accountQueries.ListAsync(cancellationToken);
        return accounts
            .OrderBy(account => account.Name, StringComparer.Ordinal)
            .ThenBy(account => account.Id)
            .ToList();
    }
}
using System.Text.Json;
using System.Text.Json.Serialization;
using Relay.Api.Http;

namespace Relay.Api.Composition;

public static class ApiServiceCollectionExtensions
{
    public static IServiceCollection AddRelayApi(this IServiceCollection services)
    {
        services.AddProblemDetails();
        services.AddExceptionHandler<UnhandledExceptionHandler>();
        services.AddValidation();
        services.ConfigureHttpJsonOptions(options =>
            options.SerializerOptions.Converters.Add(
                new JsonStringEnumConverter(JsonNamingPolicy.SnakeCaseLower, allowIntegerValues: false)));
        return services;
    }
}
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace Relay.Api.Http;

public sealed partial class UnhandledExceptionHandler(
    IProblemDetailsService problemDetailsService,
    ILogger<UnhandledExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        LogUnhandledException(logger, exception, httpContext.Request.Method, httpContext.Request.Path);

        httpContext.Response.StatusCode = StatusCodes.Status500InternalServerError;
        return await problemDetailsService.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            ProblemDetails = new ProblemDetails
            {
                Status = StatusCodes.Status500InternalServerError,
                Title = "An unexpected error occurred.",
            },
        });
    }

    [LoggerMessage(Level = LogLevel.Error, Message = "Unhandled exception for {Method} {Path}")]
    private static partial void LogUnhandledException(ILogger logger, Exception exception, string method, PathString path);
}
